/* @autogenerated */
package net.civeira.phylax.features.oauth.authentication.infrastructure.driver.html.step;

import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Locale;
import java.util.Optional;
import java.util.Set;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.ws.rs.core.NewCookie;
import jakarta.ws.rs.core.Response;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.infrastructure.CurrentRequest;
import net.civeira.phylax.features.oauth.authentication.domain.AuthenticationChallege;
import net.civeira.phylax.features.oauth.authentication.domain.ChallengesState;
import net.civeira.phylax.features.oauth.authentication.domain.exception.AuthenticationException;
import net.civeira.phylax.features.oauth.theme.domain.gateway.DecoratePageGateway;
import net.civeira.phylax.features.oauth.authentication.infrastructure.driver.html.AuthorizeHtml;
import net.civeira.phylax.features.oauth.authentication.infrastructure.driver.html.OidcStep;
import net.civeira.phylax.features.oauth.authentication.infrastructure.driver.html.SecureHtmlBuilder;
import net.civeira.phylax.features.oauth.authentication.infrastructure.driver.html.SecureHtmlBuilder.EncrytFieldTransfer;
import net.civeira.phylax.features.oauth.authentication.infrastructure.driver.html.StepInput;
import net.civeira.phylax.features.oauth.authentication.infrastructure.driver.html.StepOutcome;
import net.civeira.phylax.features.oauth.user.application.ChangePasswordUsecase;

/**
 * OIDC step for password recovery flows.
 *
 * Handles the {@code step=send-recover} form submission (sends recovery email). Not triggered by an
 * authentication exception — recovery is user-initiated.
 *
 * Also exposes {@link #allowRecover}, {@link #doPaintRecoverForm}, {@link #doPaintWaitRecover}, and
 * {@link #doExecFinal} for direct use by the controller's recovery endpoints.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class RecoverStep implements OidcStep {

  private final SecureHtmlBuilder securer;
  private final DecoratePageGateway decorator;
  private final ChangePasswordUsecase changePasswordUsecase;
  private final CurrentRequest current;

  @Override
  public AuthenticationChallege challenge() {
    return null;
  }

  @Override
  public Class<? extends AuthenticationException> challengeException() {
    return null;
  }

  @Override
  public Set<String> stepNames() {
    return Set.of("send-recover");
  }

  @Override
  public Set<String> initialStepNames() {
    return Set.of("show-recover");
  }

  @Override
  public Optional<Response> paintInitial(StepInput input, String error) {
    return Optional.of(doPaintRecoverForm(input, null));
  }

  @Override
  public Response paint(StepInput input, NewCookie preSession) {
    throw new IllegalStateException("RecoverStep is not triggered by a challenge exception");
  }

  @Override
  public Optional<StepOutcome> process(StepInput input) {
    if (!"send-recover".equals(input.step())) {
      return Optional.empty();
    }
    if (!changePasswordUsecase.allowRecover(input.getRequest().getTenant())) {
      return Optional.of(new StepOutcome.Render(
          doPaintRecoverForm(input, AuthorizeHtml.i18n(input.locale(), "recover.save-error"))));
    }
    String username = AuthorizeHtml.first(input.getFormParams(), "username");
    String url = issuer(input.getRequest().getTenant()) + "/recover" + "?username="
        + URLEncoder.encode(username, StandardCharsets.UTF_8) + "&client_id="
        + URLEncoder.encode(input.getClientDetails().getClientId(), StandardCharsets.UTF_8)
        + input.getRequest().encodeInUrl() + "&recovercode=";
    changePasswordUsecase.requestForChange(url, input.getRequest().getTenant(), username);
    return Optional.of(new StepOutcome.Render(securer
        .secureRedirectResponse(Response.status(302).location(AuthorizeHtml.buildUrl(url)))));
  }

  /**
   * Returns whether password recovery is allowed for the given tenant.
   */
  public boolean allowRecover(String tenant) {
    return changePasswordUsecase.allowRecover(tenant);
  }

  /**
   * Renders the initial recovery request form (user enters email/username).
   */
  private Response doPaintRecoverForm(StepInput input, String msg) {
    String js = securer.configureScripts(securer.addSign("sign"), securer.focusOn("username"));
    Locale locale = input.locale();

    String title = AuthorizeHtml.i18n(locale, "recover.title");
    String error = AuthorizeHtml.i18n(locale, "recover.error-format", msg);
    String help = AuthorizeHtml.i18n(locale, "recover.help");
    String email = AuthorizeHtml.i18n(locale, "recover.email");
    String send = AuthorizeHtml.i18n(locale, "recover.send");
    String backLabel = AuthorizeHtml.i18n(locale, "recover.back-label");
    String backText = AuthorizeHtml.i18n(locale, "recover.back-text",
        "<input class=\"inline\" type=\"submit\" value=\"" + backLabel + "\" />");

    return securer.secureHtmlResponse(Response.ok(decorator.getFullPage(input.tenant(), "Recover",
        js + "<h1>" + title + "</h1>" + "<p>" + help + "</p>"
            + (null == msg ? "" : "<p class=\"error\">" + error + "</p>") + "<form method=\"POST\">"
            + "<input type=\"hidden\" name=\"csid\" id=\"sign\" />" + "<label>" + email
            + "<input type=\"text\" name=\"username\" id=\"username\" value=\"\" /></label>"
            + "<input type=\"hidden\" name=\"step\" value=\"send-recover\" />"
            + "<input class=\"primary-button action-button\" type=\"submit\" value=\"" + send
            + "\" />" + "</form>" + "<form method=\"POST\">"
            + "<input class=\"inline\" type=\"hidden\" name=\"step\" />" + "<p>" + backText + "</p>"
            + "</form>",
        locale)).type(AuthorizeHtml.TEXT_HTML));
  }

  /**
   * Renders the recovery code form (user enters new password after clicking email link).
   */
  public Response doPaintWaitRecover(StepInput input, String msg, String username,
      String recoverCode) {
    String js = securer.configureScripts(securer.addSign("sign"),
        securer.cypher(
            Arrays.asList(
                EncrytFieldTransfer.builder().from("type_password").to("password").build(),
                EncrytFieldTransfer.builder().from("type_code").to("code").build()),
            "recover"),
        securer.focusOn("type_code"));
    Locale locale = input.locale();
    String title = AuthorizeHtml.i18n(locale, "recover.verify-title");
    String help = AuthorizeHtml.i18n(locale, "recover.verify-help");
    String codeLabel = AuthorizeHtml.i18n(locale, "recover.verify-code");
    String passwordLabel = AuthorizeHtml.i18n(locale, "recover.verify-password");
    String send = AuthorizeHtml.i18n(locale, "recover.verify-send");
    String backLabel = AuthorizeHtml.i18n(locale, "recover.verify-back-label");
    String backText = AuthorizeHtml.i18n(locale, "recover.verify-back-text",
        "<input class=\"inline\" type=\"submit\" value=\"" + backLabel + "\" />");
    String error = AuthorizeHtml.i18n(locale, "recover.error-format", msg);
    return securer.secureHtmlResponse(Response.ok(decorator.getFullPage(input.tenant(), "Recover",
        js + "<h1>" + title + "</h1>" + "<p>" + help + "</p>"
            + (null == msg ? "" : "<p class=\"error\">" + error + "</p>")
            + "<form id=\"recover\" method=\"POST\">"
            + "<input type=\"hidden\" name=\"csid\" id=\"sign\" />"
            + "<label>Username: <input type=\"text\" name=\"username\" value=\"" + username
            + "\" /></label>" + "<input type=\"hidden\" id=\"code\" name=\"code\" value=\"\" />"
            + "<label>" + codeLabel + ": <input type=\"text\" id=\"type_code\" value=\""
            + (null == recoverCode ? "" : recoverCode) + "\" /></label>"
            + "<label>" + passwordLabel
            + ": <input type=\"password\" id=\"type_password\" value=\"\" /></label>"
            + "<input type=\"hidden\" id=\"password\" name=\"password\" value=\"\" />"
            + "<input class=\"primary-button action-button\" type=\"submit\" value=\"" + send
            + "\" />" + "</form>" + "<form method=\"POST\">"
            + "<input type=\"hidden\" name=\"step\" value=\"\" />" + "<p>" + backText + "</p>"
            + "</form>",
        locale)).type(AuthorizeHtml.TEXT_HTML));
  }

  /**
   * Processes the final recovery code submission and resumes the auth flow.
   */
  public Optional<StepOutcome> doExecFinal(StepInput input) {
    String pass = securer.decrypt(AuthorizeHtml.first(input.getFormParams(), "password"));
    String code = securer.decrypt(AuthorizeHtml.first(input.getFormParams(), "code"));
    String usernameParam = AuthorizeHtml.first(input.getFormParams(), "username");
    Optional<String> validatedUsername = changePasswordUsecase
        .validateChangeRequest(input.getRequest().getTenant(), usernameParam, code, pass);
    if (validatedUsername.isPresent()) {
      String username = validatedUsername.get();
      ChallengesState state =
          input.getChallenges().orElseGet(() -> ChallengesState.empty(username));
      return Optional.of(
          new StepOutcome.Proceed(username, input.getClientDetails(), input.getRequest(), state));
    } else {
      String recoverCode = AuthorizeHtml.first(input.getFormParams(), "recovercode");
      String username = AuthorizeHtml.first(input.getFormParams(), "username");
      return Optional.of(new StepOutcome.Render(doPaintWaitRecover(input,
          AuthorizeHtml.i18n(input.locale(), "recover.wrong-code"), username, recoverCode)));
    }
  }

  private String issuer(String tenant) {
    return current.getPublicHost() + "/oauth/openid/" + tenant;
  }
}
